// Body: { state, questions, debias?: 1..3 } in TypeSafe System One format.
// Small models favour some option positions, so with debias > 1 every choice question is asked
// again with its options rotated; the next step averages the runs. No labels needed.
const req = $input.first().json;
const body = req.body || {};
const requestedBy = (req.headers && req.headers['x-requested-by']) || 'unknown';
const TYPES = ['choice', 'score', 'noul'];

if (!body.state || typeof body.state !== 'object') throw new Error('body.state must be an object');
if (!body.questions || typeof body.questions !== 'object' || !Object.keys(body.questions).length) throw new Error('body.questions must be a non-empty object');
for (const [key, q] of Object.entries(body.questions)) {
  if (!TYPES.includes(q.type)) throw new Error(`questions.${key}.type must be one of ${TYPES.join(', ')}`);
}

const runs = Math.max(1, Math.min(3, Number(body.debias) || 1));
const rotate = (obj, k) => {
  const entries = Object.entries(obj);
  const n = entries.length;
  return Object.fromEntries(entries.map((_, i) => entries[(i + k) % n]));
};

return Array.from({ length: runs }, (_, run) => {
  const questions = Object.fromEntries(Object.entries(body.questions).map(([key, q]) => [
    key,
    q.type === 'choice' && q.criteria && !Array.isArray(q.criteria) && run > 0
      ? { ...q, criteria: rotate(q.criteria, run) }
      : q,
  ]));
  return { json: { run, runs, requested_by: requestedBy, request: { state: body.state, questions } } };
});

// Average the probabilities of all runs, then recompute the TypeSafe fields.
const results = $input.all().map(i => i.json);
const first = $('Validate and rotate options').first().json;
const original = first.request.questions;

const mean = list => list.reduce((s, v) => s + v, 0) / list.length;
const avgMaps = maps => {
  const keys = Object.keys(maps[0] || {});
  return Object.fromEntries(keys.map(k => [k, +mean(maps.map(m => m[k] ?? 0)).toFixed(4)]));
};

const answers = {};
for (const [key, q] of Object.entries(original)) {
  const runs = results.map(r => r.answers?.[key]).filter(Boolean);
  if (!runs.length) continue;
  if (q.type === 'noul') {
    answers[key] = { type: 'noul', noul: +mean(runs.map(r => r.noul)).toFixed(4) };
    continue;
  }
  const probabilities = avgMaps(runs.map(r => r.probabilities));
  const [best, pMax] = Object.entries(probabilities).sort((a, b) => b[1] - a[1])[0];
  const n = Object.keys(probabilities).length;
  if (q.type === 'choice') {
    // TypeSafe definition: 0 when uniform, 1 when one option has all the mass.
    answers[key] = { type: 'choice', choice: best, x_p_max: pMax, confidence: +((n * pMax - 1) / (n - 1)).toFixed(4), probabilities };
  } else {
    const score = Object.entries(probabilities).reduce((s, [lvl, p]) => s + Number(lvl) * p, 0);
    answers[key] = { type: 'score', score: +score.toFixed(3), level: Number(best), x_p_max: pMax, probabilities, legend: runs[0].legend };
  }
}

return [{
  json: {
    response: {
      answers,
      model: results[0]?.model,
      runs: results.length,
      latency_ms: Math.max(...results.map(r => r.x_latency_ms || 0)),
    },
    log: {
      decided_at: new Date().toISOString(),
      requested_by: first.requested_by,
      question_keys: Object.keys(original).join(','),
      request: JSON.stringify(first.request).slice(0, 20000),
      answers: JSON.stringify(answers),
      model: results[0]?.model || null,
      runs: results.length,
      latency_ms: Math.max(...results.map(r => r.x_latency_ms || 0)),
      outcome: null,
    },
  },
}];
